 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            pts = set()
            while q:
                y, x = q.popleft()
                pts.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, pts))
    return result


def _is_l(pts):
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    for r in (r0, r1):
        for c in (c0, c1):
            if pts == ({(r, x) for x in range(c0, c1 + 1)} |
                       {(y, c) for y in range(r0, r1 + 1)}):
                return r, c, (1 if r == r0 else -1), (1 if c == c0 else -1)
    return None


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    markers = [(len(p), col, p, _is_l(p)) for col, p in comps if _is_l(p)]
    if not markers:
        return [row[:] for row in grid]
    _, marker_color, marker, corner = max(markers, key=lambda x: x[0])
    r, c, vd, hd = corner
    # Recolor the component occupying the open quadrant opposite the L arms.
    choices = []
    for color, pts in comps:
        if color == marker_color or _is_l(pts):
            continue
        cy = sum(y for y, x in pts) / len(pts)
        cx = sum(x for y, x in pts) / len(pts)
        if (cy-r)*(-vd) <= 0 or (cx-c)*(-hd) <= 0:
            continue
        # Retain only candidates whose bounding boxes fall fully into the open quadrant.
        choices.append((abs(cy-r)+abs(cx-c), -len(pts), pts))
    if not choices:
        # If no object is strictly in the open quadrant, choose on the horizontal-opposite side.
        for color, pts in comps:
            if color == marker_color or _is_l(pts):
                continue
            cx = sum(x for y, x in pts) / len(pts)
            if (cx-c)*(-hd) > 0:
                cy = sum(y for y, x in pts) / len(pts)
                choices.append((abs(cy-r)+abs(cx-c), -len(pts), pts))
    if not choices:
        return [row[:] for row in grid]
    target = min(choices, key=lambda x: (x[0], x[1]))[2]
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = marker_color
    return out
